BEGIN;

-- Fix brand_scores_v to order dims matching app DIMENSIONS constant
-- (website, pricing, local, floor, pro) instead of alphabetical
CREATE OR REPLACE VIEW brand_scores_v AS
SELECT
  bds.brand_id    AS id,
  bds.brand_name  AS name,
  bds.brand_slug  AS slug,
  b.domain,
  b.logo_url,
  b.categories,
  b.claimed_by,
  b.description,
  b.created_at,
  round(sum(bds.dim_score)::numeric, 0)::int AS score,
  array_agg(bds.dim_score ORDER BY
    CASE bds.dimension_key
      WHEN 'website' THEN 1
      WHEN 'pricing' THEN 2
      WHEN 'local'   THEN 3
      WHEN 'floor'   THEN 4
      WHEN 'pro'     THEN 5
    END
  ) AS dims,
  max(bds.review_count)::int AS review_count,
  '0' AS change,
  array[0,0,0,0,0]::int[] AS spark
FROM brand_dim_scores_v bds
JOIN brands b ON b.id = bds.brand_id
GROUP BY bds.brand_id, bds.brand_name, bds.brand_slug,
         b.domain, b.logo_url, b.categories, b.claimed_by,
         b.description, b.created_at;

-- Create system auth user for survey import
  instance_id, id, aud, role, email, encrypted_password,
  email_confirmed_at, created_at, updated_at,
  raw_app_meta_data, raw_user_meta_data
) VALUES (
  '00000000-0000-0000-0000-000000000000'::uuid,
  '00000000-0000-0000-0000-b01500400001'::uuid,
  'authenticated', 'authenticated',
  'survey-import@bpi.internal',
  crypt('not-a-real-password', gen_salt('bf')),
  now(), now(), now(),
  '{"provider":"email","providers":["email"]}'::jsonb,
  '{"role":"retailer"}'::jsonb
) ON CONFLICT (id) DO NOTHING;

VALUES ('00000000-0000-0000-0000-b01500400001'::uuid, 'survey-import@bpi.internal', 'retailer', 'ENDVR Survey Import', now(), now())
ON CONFLICT (id) DO NOTHING;

-- Remove previous survey import data (safe to re-run)
DELETE FROM review_comments WHERE review_id IN (SELECT id FROM reviews WHERE reviewer_id = '00000000-0000-0000-0000-b01500400001'::uuid);
DELETE FROM review_scores WHERE review_id IN (SELECT id FROM reviews WHERE reviewer_id = '00000000-0000-0000-0000-b01500400001'::uuid);
DELETE FROM reviews WHERE reviewer_id = '00000000-0000-0000-0000-b01500400001'::uuid;

