INSERT INTO review_comments (review_id, dimension_key, comment_text) VALUES ('e8e5f266-7299-44f9-b121-e1a7dd1e4740'::uuid, '_pros', 'Adidas has always made high quality products, specifically its footwear. The large variety of footwear Adidas carries including lifestyle, racing, and recreational running shoes makes this company extremely appealing. We have had the sales rep come into our store multiple times and it has greatly impacted our product knowledge, which we can they relay to customers. Many customers already have knowledge of the high quality adidas offers.'), ('e8e5f266-7299-44f9-b121-e1a7dd1e4740'::uuid, '_cons', 'It would be nice if Adidas had a pro deal to make it easier for us sales associates to try the products first hand.');
