INSERT INTO review_comments (review_id, dimension_key, comment_text) VALUES ('707ef75e-9b0e-4bb1-af56-cabf8f987ac8'::uuid, '_pros', 'Rep visits to our store greatly impact how we sell arcteryx product (clothing and footwear)! it’s is greatly beneficial learning which products are better for different situations. Although most products are highly priced, the quality is top notch and it is easy to relay this to customers. The pro deal is a great way for us sales associates to interact with product first hand.'), ('707ef75e-9b0e-4bb1-af56-cabf8f987ac8'::uuid, '_cons', 'Honestly there is not much to say for this one other than the price point compared to its main competitors.');
