INSERT INTO review_comments (review_id, dimension_key, comment_text) VALUES ('8ac75a23-4eb9-473c-8e78-ce14b94a8ea2'::uuid, '_pros', 'While the collection is attractive, many frames feature bold and decorative styling. There are fewer simple, minimalist options, which can make it harder to fit customers looking for basic everyday eyewear. The collection tends to appeal more to mature female customers than to younger shoppers.'), ('8ac75a23-4eb9-473c-8e78-ce14b94a8ea2'::uuid, '_cons', 'Carolina Herrera offers stylish and recognizable designs, strong brand recognition, and good quality at accessible price points. The collection appeals to customers looking for fashionable and elegant eyewear, making the brand easy to recommend and sell.');
INSERT INTO reviews (id, reviewer_id, brand_id, status, country, store_city, created_at, updated_at) VALUES ('a165a592-091d-45e1-a4bf-7bd908a471f3'::uuid, '00000000-0000-0000-0000-b01500400001'::uuid, (SELECT id FROM brands WHERE slug = 'carrera'), 'published', 'United States', 'New York', '2026-05-29 21:00:46'::timestamptz, '2026-05-29 21:00:46'::timestamptz);
INSERT INTO review_scores (review_id, dimension_key, sub_component_key, score) VALUES ('a165a592-091d-45e1-a4bf-7bd908a471f3'::uuid, 'website', 'overall', 5), ('a165a592-091d-45e1-a4bf-7bd908a471f3'::uuid, 'pricing', 'overall', 3), ('a165a592-091d-45e1-a4bf-7bd908a471f3'::uuid, 'local', 'overall', 3), ('a165a592-091d-45e1-a4bf-7bd908a471f3'::uuid, 'floor', 'overall', 5), ('a165a592-091d-45e1-a4bf-7bd908a471f3'::uuid, 'pro', 'overall', 3);
INSERT INTO review_comments (review_id, dimension_key, comment_text) VALUES ('a165a592-091d-45e1-a4bf-7bd908a471f3'::uuid, '_pros', 'Carrera makes products easy to recommend thanks to strong brand recognition, attractive merchandising, and consistent product quality. Their styles appeal to a wide range of customers, and the brand provides solid training and support that helps staff feel confident selling the product.'), ('a165a592-091d-45e1-a4bf-7bd908a471f3'::uuid, '_cons', 'Carrera makes products easy to recommend thanks to strong brand recognition, attractive merchandising, and consistent product quality. Their styles appeal to a wide range of customers, and the brand provides solid training and support that helps staff feel confident selling the product.');
