INSERT INTO review_scores (review_id, dimension_key, sub_component_key, score) VALUES ('738f26fa-ca56-442d-8c69-32a6b3585d8a'::uuid, 'website', 'overall', 4), ('738f26fa-ca56-442d-8c69-32a6b3585d8a'::uuid, 'pricing', 'overall', 4), ('738f26fa-ca56-442d-8c69-32a6b3585d8a'::uuid, 'local', 'overall', 3), ('738f26fa-ca56-442d-8c69-32a6b3585d8a'::uuid, 'floor', 'overall', 1), ('738f26fa-ca56-442d-8c69-32a6b3585d8a'::uuid, 'pro', 'overall', 3);
INSERT INTO review_comments (review_id, dimension_key, comment_text) VALUES ('738f26fa-ca56-442d-8c69-32a6b3585d8a'::uuid, '_pros', 'The name ‘Nike’ itself attracts a ton of customers. their ability to market online is top level'), ('738f26fa-ca56-442d-8c69-32a6b3585d8a'::uuid, '_cons', 'There are many weaknesses to Nike. They never bring any reps in to give a run down on shoes. The models they create seem to be lagging behind compared to other competitors. There is also no pro deal for Nike at the moment. it would be nice if they created wider shoes as most of their shoes fit slimmer.');
