INSERT INTO review_comments (review_id, dimension_key, comment_text) VALUES ('01a57c29-a5ce-42a3-a5fd-0c27d781a3e4'::uuid, '_pros', 'The name itself draws customers in! Their marketing in store on line is next to none and it seems they take pride in keeping up with new technology and trends. The company has also pioneered the thicker soles on running shoes and this also draws customers in. it would be great to get some sort of pro deal for Hoka at some point'), ('01a57c29-a5ce-42a3-a5fd-0c27d781a3e4'::uuid, '_cons', 'Alrhough the shoes are not extremely pricey, they rarely run sales. When they do run sales, the shoes fly off of our shelves');
