INSERT INTO review_comments (review_id, dimension_key, comment_text) VALUES ('4645f977-5e07-4b45-9130-b43fc74dfb4d'::uuid, '_pros', 'Most Ecco shoes and sandals are made quality and durable. I wear Ecco dress shoes on the sales floor and they are comfortable very supportive and they hold up extremely well. The Ecco rep for our store is super nice and knowledgeable, he comes often and is always eager to help train and provide information about the products.'), ('4645f977-5e07-4b45-9130-b43fc74dfb4d'::uuid, '_cons', 'The price sometimes is too high for our market and people aren’t comfortable spending the money. I wish our store had a bit better selection.');
