INSERT INTO review_comments (review_id, dimension_key, comment_text) VALUES ('97c4b395-a1e0-4800-986b-7dabc37a67f2'::uuid, '_pros', 'The fabric of the clothing is next to none! It is silky smooth and something customers can’t resist. The price point is definitely higher than competing products, however the high quality of the products is visible and the price is justified. It is also very easy to sell this product as I personally love it and when customers buy one they always come back for more! it'), ('97c4b395-a1e0-4800-986b-7dabc37a67f2'::uuid, '_cons', 'Strictly the price point (even though it is justifiable). I also feel we could use more advertisement for our store so customers are aware that we carry Vuori.');
